 const everyday={
  '8-6':[['Trabalhadores da mineração','Grande parte da extração de ouro dependia do trabalho compulsório de africanos escravizados. Havia também garimpeiros livres, artesãos e comerciantes.'],['Vida nas vilas mineiras','A mineração atraiu moradores, comerciantes e religiosos. Nas vilas, igrejas e irmandades organizavam parte da sociabilidade.'],['Fiscalidade e conflitos','A cobrança de tributos pela Coroa agravava tensões entre moradores, mineradores e autoridades coloniais.']],
  '8-7':[['Moradores do Rio de Janeiro','A chegada da corte transformou a capital, aumentando a demanda por moradias, serviços e abastecimento.'],['Trabalho e escravidão','A independência política não aboliu a escravidão nem eliminou as hierarquias sociais.'],['Participação na independência','Mulheres, indígenas, negros livres e escravizados participaram de diferentes conflitos e mobilizações, embora sua atuação nem sempre fosse reconhecida.']],
  '8-8':[['Cidadania restrita','A Constituição de 1824 organizou eleições indiretas e censitárias, excluindo grande parte da população da participação política.'],['Rebeliões provinciais','As revoltas regenciais reuniram grupos com interesses distintos, de elites locais a trabalhadores e pessoas escravizadas.'],['Mulheres e trabalho','Mulheres atuavam no comércio, na produção doméstica e em redes de solidariedade, apesar de sua exclusão dos direitos políticos.']],
  '8-9':[['Trabalho no café','A expansão cafeeira baseou-se inicialmente na escravidão e passou a incorporar imigrantes e diferentes formas de trabalho livre.'],['Vida urbana','Ferrovias, imprensa e serviços ampliaram as conexões entre cidades; o acesso à educação e à riqueza permaneceu desigual.'],['Soldados e famílias','A Guerra do Paraguai mobilizou voluntários, recrutados e escravizados libertados para o serviço militar, afetando numerosas famílias.']],
  '8-10':[['Redes de resistência','Pessoas escravizadas mobilizaram fugas, ações judiciais, redes de apoio e negociações para buscar liberdade.'],['Abolicionismo popular','Jornalistas, advogados, artistas, trabalhadores e associações organizaram campanhas, arrecadações e manifestações.'],['Pós-abolição','A liberdade jurídica não garantiu acesso a terra, moradia, escolarização ou trabalho digno à população liberta.']],
  '8-11':[['Cidadania e desigualdade','As revoluções liberais defendiam direitos e constituições, mas frequentemente restringiam o voto a homens com renda ou propriedade.'],['Trabalhadores urbanos','A industrialização ampliou o trabalho assalariado e a organização coletiva por melhores condições de vida.'],['Identidades nacionais','Línguas, memórias, símbolos e tradições foram mobilizados por movimentos nacionalistas na Europa.']],
  '8-12':[['Populações colonizadas','A ocupação europeia alterou fronteiras, formas de trabalho e sistemas políticos, mas encontrou diferentes formas de resistência.'],['Trabalho colonial','Empresas e autoridades coloniais exploraram mão de obra e recursos, frequentemente com coerção e violência.'],['Hierarquias raciais','Ideologias racistas foram utilizadas para justificar a dominação; povos colonizados contestaram essas hierarquias.']],
  '9-3':[['Camponeses','A distribuição desigual da terra e as dificuldades rurais alimentaram reivindicações por reforma agrária.'],['Operários e sovietes','Trabalhadores urbanos organizaram greves e conselhos de representação chamados sovietes.'],['Mulheres na revolução','Em 1917, manifestações de trabalhadoras por pão e melhores condições contribuíram para a queda do czarismo.']],
  '9-4':[['Desemprego e pobreza','A crise de 1929 afetou famílias, moradias e consumo; redes de solidariedade e políticas públicas tornaram-se essenciais.'],['Propaganda e juventude','Regimes autoritários buscaram controlar a imprensa, as escolas e a formação política dos jovens.'],['Perseguição e exclusão','O nazismo promoveu o antissemitismo e a perseguição a grupos considerados inimigos do regime.']],
  '9-6':[['Direitos trabalhistas','A legislação trabalhista consolidada em 1943 regulamentou relações formais de trabalho; muitos trabalhadores rurais ficaram inicialmente excluídos.'],['Rádio e cultura popular','O rádio ampliou a circulação de notícias, músicas e discursos oficiais, tornando-se um importante meio de comunicação.'],['Censura e participação','O Estado Novo restringiu liberdades políticas e sindicais enquanto promovia a imagem de um governo protetor dos trabalhadores.']],
  '9-8':[['Propaganda e medo nuclear','A rivalidade entre as superpotências influenciou cinema, notícias, pesquisas científicas e a percepção cotidiana de ameaças.'],['Divisão de famílias','A divisão de Berlim separou parentes e comunidades, restringindo deslocamentos por décadas.'],['Movimentos pela paz','Organizações e manifestantes de diferentes países contestaram guerras, armas nucleares e intervenções internacionais.']],
  '9-9':[['Censura e cultura','Artistas, jornalistas e escritores enfrentaram restrições; muitos recorreram à metáfora e à organização coletiva.'],['Trabalhadores e mobilização','Greves, associações de bairro e movimentos por direitos questionaram a repressão e a política salarial.'],['Memória das vítimas','Familiares e movimentos de direitos humanos lutaram por esclarecimento de violações e reconhecimento das vítimas.']],
  '9-10':[['Juventude e contracultura','Música, vestuário e comportamentos expressavam críticas à guerra, ao consumismo e a valores tradicionais.'],['Movimentos feministas','Mulheres reivindicaram autonomia, igualdade no trabalho, direitos reprodutivos e participação política.'],['Direitos civis','Movimentos negros e LGBTQIA+ enfrentaram segregação e discriminação, conquistando visibilidade e direitos.']],
  '9-11':[['Cidadania após 1988','A Constituição ampliou direitos sociais e instituiu bases para políticas como o SUS.'],['Economia familiar','Inflação, desemprego e diferentes políticas econômicas influenciaram o orçamento e as condições de vida das famílias.'],['Participação democrática','Eleições, associações e movimentos sociais tornaram-se importantes espaços de disputa por direitos.']],
  '9-12':[['Trabalho digital','Computadores e internet transformaram profissões, comunicação e formas de trabalho, mas o acesso à tecnologia permanece desigual.'],['Migrações e identidades','Migrações internacionais conectam culturas e sociedades, ao mesmo tempo que expõem pessoas a discriminação e dificuldades de integração.'],['Circulação de informação','Redes digitais ampliam o acesso a informações e também exigem cuidado com desinformação e privacidade.']],
  '1-1':[['Caça e coleta','Grupos humanos desenvolveram instrumentos, conhecimentos ambientais e formas de cooperação para obter alimento.'],['Sedentarização','A agricultura possibilitou aldeias permanentes em algumas regiões, sem eliminar imediatamente modos de vida móveis.'],['Memória e ritual','Sepultamentos, objetos e pinturas rupestres ajudam a investigar práticas simbólicas e sociais.']],
  '1-2':[['Cidadania antiga','Nas cidades gregas e em Roma, direitos políticos variavam conforme condição jurídica, origem, gênero e liberdade.'],['Trabalho livre e escravizado','A escravidão coexistiu com diferentes formas de trabalho e sustentou parte importante das economias antigas.'],['Espaços públicos','Praças, mercados, templos e espetáculos eram locais de sociabilidade, comércio e expressão de poder.']],
  '1-3':[['Vida rural','A maior parte da população europeia vivia no campo, produzindo alimentos e mantendo redes locais.'],['Mosteiros','Comunidades monásticas preservavam textos, organizavam devoção e ofereciam assistência em diferentes regiões.']],
  '1-4':[['Servos e senhores','Obrigações, tributos e direitos sobre a terra marcavam relações de dependência no mundo feudal.'],['Cidades e ofícios','Artesãos, mercadores e corporações organizaram atividades econômicas nas cidades medievais.']],
  '1-5':[['Oficinas de arte','Aprendizes e mestres trabalhavam em oficinas apoiadas por encomendas de elites, igrejas e governos.'],['Livros e leitores','A imprensa ampliou a circulação de textos e imagens, embora o acesso à alfabetização fosse desigual.']],
  '1-6':[['Práticas religiosas','Diferentes interpretações da fé alteraram cultos, ensino, organização comunitária e a relação com autoridades religiosas.'],['Comunidades e conflitos','As reformas religiosas provocaram debates, perseguições, migrações e guerras, afetando a vida das famílias.']],
  '1-7':[['Cortes e privilégios','A nobreza mantinha privilégios sociais e buscava influência junto a monarcas e suas cortes.'],['Comércio e trabalho','Mercadores, artesãos e trabalhadores participavam de economias transformadas pela expansão comercial.']],
  '1-8':[['Povos originários','A conquista europeia atingiu sociedades indígenas diversas, que desenvolveram estratégias de negociação, resistência e sobrevivência.'],['Viagens e encontros','Marinheiros, intérpretes, comerciantes e missionários participaram de contatos entre diferentes sociedades.']],
  '1-9':[['Engenhos e trabalho','A produção açucareira dependia da terra, do comércio atlântico e da exploração de trabalhadores escravizados.'],['Redes de resistência','Pessoas escravizadas preservaram saberes, criaram comunidades e resistiram à violência por diferentes meios.']],
  '1-10':[['Vilas e irmandades','O crescimento das vilas mineradoras favoreceu redes de comércio, devoção, assistência e sociabilidade.'],['Desigualdades coloniais','A prosperidade da mineração conviveu com escravização, tributação e desigualdade de condições de vida.']]
 };
