  const precise=(specialThemes[chapterKey]||[]).find(([pattern,file])=>new RegExp(pattern,'i').test(r.title)&&!usedPhotos.has(keyOf(asHistorical([file,'']).url)));
  if(precise){assign(r,asHistorical(precise.slice(1)));continue}
  const raw=r.photo,key=keyOf(raw);
  if(raw&&!raw.startsWith('data:')&&photoCounts.get(key)===1&&!usedPhotos.has(key)){const source=originalCards[i]?.querySelector('a[href*="commons.wikimedia.org/wiki/File"]')?.href;if(!r.credit&&source)r.credit={source,caption:r.alt||'Fonte histórica'};usedPhotos.add(key);continue}
  const match=[...moreThemes,...thematicImages].find(([pattern,file])=>new RegExp(pattern,'i').test(r.title)&&!usedPhotos.has(keyOf(asHistorical([file,'']).url)));
  if(match){assign(r,asHistorical(match.slice(1)));continue}
  if(i===0&&contextualAsset&&!usedPhotos.has(keyOf(contextualAsset.url))){assign(r,contextualAsset);continue}
  if(raw&&!raw.startsWith('data:')&&!usedPhotos.has(key)&&i===0){usedPhotos.add(key);continue}
  // Do not misrepresent an unrelated or repeated image as a station-specific source.
  r.photo=null;r.alt=null;r.credit=null;
