 if(meta.year===8&&meta.id===1){
  const stations=[
   ['Hyacinthe Rigaud - Retrato do Rei Luís XIV.jpg','Retrato de Luís XIV, Hyacinthe Rigaud: o absolutismo na Europa.','O Antigo Regime reunia monarquias de poder centralizado, sociedades marcadas por privilégios estamentais e práticas mercantilistas. A expansão comercial e a ascensão da burguesia contribuíram para questionar essa organização.'],
   ['François-Marie Arouet, dit Voltaire (1694-1778) portrait (A).jpg','Retrato histórico de Voltaire.','O Iluminismo foi um movimento intelectual dos séculos XVII e XVIII que valorizou a razão, a investigação e o pensamento crítico. Seus pensadores questionaram tradições, intolerância e privilégios, propondo mudanças na política e na sociedade.'],
   ["Détail frontispice encyclopédie Diderot D'Alembert.png",'Detalhe do frontispício da Enciclopédia de Diderot e d’Alembert.','O crescimento das cidades, a circulação de livros e as descobertas científicas ampliaram os debates sobre conhecimento e autoridade. Salões, academias e a Enciclopédia tornaram-se importantes espaços de divulgação de novas ideias.'],
   ['Portrait de Montesquieu, D.5902.jpg','Retrato de Montesquieu, século XVIII.','Os pensadores iluministas defenderam a liberdade de pensamento, a tolerância religiosa e a crítica aos privilégios. Montesquieu propôs a separação dos poderes; outros autores discutiram direitos, soberania e limites da autoridade política.'],
   ['StormingBastille.jpg','Representação da tomada da Bastilha, 14 de julho de 1789.','As ideias iluministas influenciaram a Independência dos Estados Unidos, a Revolução Francesa e movimentos políticos posteriores. Conceitos de liberdade, igualdade e direitos ajudaram a contestar estruturas tradicionais de poder.'],
   ['Wealth of Nations title.jpg','Página de rosto de A Riqueza das Nações, 1776.','O liberalismo econômico clássico criticou restrições mercantilistas e defendeu a liberdade de iniciativa, a concorrência e o comércio. Adam Smith examinou o funcionamento dos mercados e a divisão do trabalho em A Riqueza das Nações.'],
   ['Balthazar nebot, il mercato di covent garden, 1737FXD.jpg','Mercado de Covent Garden, Balthazar Nebot, 1737.','Entre as características do liberalismo econômico estão a propriedade privada, a liberdade de comércio, a concorrência e a formação de preços no mercado. A atuação estatal deveria garantir instituições e regras, em vez de controlar toda a atividade econômica.'],
   ['Dutch Merchants Sketched at Amsterdam MET DP872181.jpg','Mercadores em Amsterdã, gravura de Thomas Rowlandson.','O liberalismo econômico valoriza a iniciativa individual e a competição, entendendo que a troca e a especialização podem estimular a produção. Diferentes autores, contudo, discutiram os limites da intervenção estatal e os efeitos sociais do mercado.'],
   ['AdamSmith.jpg','Retrato de Adam Smith baseado no medalhão de James Tassie.','Adam Smith estudou a divisão do trabalho e a formação da riqueza. David Ricardo analisou a distribuição de renda e o comércio entre países. Suas contribuições formaram parte da tradição econômica clássica.'],
   ['William Hogarth - Gin Lane.jpg','Gin Lane, gravura de William Hogarth, 1751: crítica social urbana.','A concorrência pode estimular produtividade, inovação e escolhas econômicas. Entretanto, mercados sem proteção social adequada podem concentrar riqueza, aprofundar desigualdades e gerar condições precárias de trabalho.']
  ];
  records.forEach((r,i)=>{const s=stations[i];if(!s)return;const asset=asHistorical(s.slice(0,2));r.photo=asset.url;r.alt=asset.caption;r.credit=asset;r.summary=s[2];const oldBody=r.body;r.body=()=>{const article=oldBody();article.prepend(node('h3','','Síntese histórica'),node('p','',s[2]));return article}});
 }
 const sourceAtlas=d.getElementById('atlas')||d.getElementById('fontes');if(sourceAtlas){const items=[contextualAsset,...records.map(r=>r.credit)].filter(x=>x?.source);const unique=new Map(items.map(x=>[x.source,x]));if(unique.size){const disclosure=node('details','portal-image-credits');disclosure.append(node('summary','','Créditos das imagens e mapas'));const list=node('ul');for(const x of unique.values()){const li=node('li'),link=node('a','',x.caption||'Fonte histórica');link.href=x.source;link.target='_blank';link.rel='noopener noreferrer';li.append(link);list.append(li)}disclosure.append(list);sourceAtlas.append(disclosure)}}
